class DatFechasCierrePeriodo extends BaseDatFechasCierrePeriodo
{

    public static function obtenerObjDatFechasCierrePeriodo($iddatcierreperiodo)
    {
        return Doctrine::getTable('DatFechasCierrePeriodo')->find($iddatcierreperiodo);
    }

    public static function obtenerFechasCierrePeriodoAbertoEntidad($idestructura)
    {
        //Devolviendo el listado
        return Doctrine_Query::create()
            ->select('*')
            ->from('DatFechasCierrePeriodo')
            ->where('identidad = ? and estado = 1', array($idestructura))
            ->fetchArray();
    }

    public static function obtenerListadoDatFechasCierrePeriodo($idestructura)
    {
    //Devolviendo el listado sin las columnas (personascaja, personascajero)
        return Doctrine_Query::create()
            ->select('idfechascierre, 
	                    fechacierre, 
	                    estado, 
                    	identidad, 
                    	montocajacup, 
                    	montocajacuc, 
                    	montocajerocup, 
                    	montocajerocuc, 
                    	estadobancocup, 
                    	estadocajacup, 
                    	estadobancocuc, 
                    	estadocajacuc')//*
            ->from('DatFechasCierrePeriodo')
            ->where('identidad = ?', array($idestructura))
            ->orderBy('idfechascierre DESC')
            ->fetchArray();
    }

    public static function obtenerListadoDatFechasCierrePeriodoEntidadesSubordinadas($arrayentidades)
    {
        //Devolviendo el listado sin las columnas (personascaja, personascajero)
        return Doctrine_Query::create()
            ->select('idfechascierre, 
	                    fechacierre, 
	                    estado, 
                    	identidad, 
                    	montocajacup, 
                    	montocajacuc, 
                    	montocajerocup, 
                    	montocajerocuc, 
                    	estadobancocup, 
                    	estadocajacup, 
                    	estadobancocuc, 
                    	estadocajacuc')//*
            ->from('DatFechasCierrePeriodo')
            ->whereIn('identidad', $arrayentidades)
            ->fetchArray();
    }

    public static function obtenerListadoPersonasCaja($idfechascierre)
    {
        //Devolviendo el listado	
		if(is_array($idfechascierre)){
			if(!empty($idfechascierre)){
            $mg = Doctrine_Manager::getInstance();
            $conn = $mg->getCurrentConnection();
			$idfechascierreimplode = implode(',', $idfechascierre);
			$sql = "select personascaja from mod_nomina.dat_fechascierreperiodos where idfechascierre in ({$idfechascierreimplode});";
            $r = $conn->fetchAll($sql);
		    return $r[0]['personascaja'];
			}
			return;
		} else{
			return Doctrine_Query::create()
            ->select('personascaja')
            ->from('DatFechasCierrePeriodo')
            ->where('idfechascierre = ?', array($idfechascierre))
            ->fetchOne()
            ->personascaja;
		}
    }

